DECISIONS=[
('V01','Ordre MCP / Repack','Ne pas déclarer une procédure officielle avant contrôle sur le site.','Responsable atelier + stock','Valider les cas brouillon, MCP soumis et Repack partiel / complet.'),
('V02','Rôles et droits','Les DocTypes mat_reco livrent System Manager ; les rôles opérateur sont une proposition.','Administrateur / responsable','Confirmer droits de lecture, écriture, soumission et annulation.'),
('V03','Chemin fournisseur','Purchase Order n’est pas requis dans toutes les réceptions.','Achats / stock','Définir quand utiliser PO → PR et quand utiliser Material Receipt Plan.'),
('V04','Double réception','Les deux circuits ne doivent pas compter deux fois les mêmes unités.','Stock','Valider l’identification du justificatif et des séries par circuit.'),
('V05','Chemins de facturation','Livraison → Facture est un parcours pédagogique, pas une obligation universelle.','Commercial / facturation','Valider les chemins directs depuis SO et les règles Update Stock.'),
('V06','Activation des scripts et fixtures','Les scripts du dépôt ne prouvent pas leur activation sur le site.','Administrateur','Vérifier scripts Quotation, Purchase Receipt, dimensions, bundles et impressions.'),
('V07','Champs de dimensions','Les noms et le report d’épaisseur doivent être contrôlés dans les métadonnées du site.','Administrateur / stock','Confirmer Purchase Receipt, Serial No et lignes commerciales.'),
('V08','Dialogue Repack SO','Une version est dans le script public, une autre dans les Client Scripts.','Administrateur','Choisir Create Repack ou Generate Repack et éviter les doublons.'),
('V09','Reconfiguration historique','Material Reconfiguration conserve un cycle spécifique et des effets sur séries.','Responsable atelier / stock','Confirmer si ce circuit reste utilisé ; tester soumission et annulation isolément.'),
('V10','Material Production Plan','Le contrôleur actuel est vide ; aucun flux automatisé démontré.','Responsable produit','Exclure, utiliser manuellement ou développer avant de former.'),
('V11','Politique déchets','Add Waiste to stock change les sorties attendues.','Responsable stock','Définir la règle et les articles / entrepôts associés.'),
('V12','Qualité et contraintes physiques','L’optimisation ne certifie pas toutes les contraintes machine ou de matériau.','Responsable atelier','Valider kerf réel, sens matière, qualité et admissibilité des variantes.'),
('V13','Coûts et mouvements réels','Le manuel décrit le code, pas une recette complète de valorisation soumise.','Stock / comptabilité','Tester réception, Repack, répartition, arrondis et annulations sur jeu de recette.'),
('V14','Captures en session ERPNext','Aucune capture en session métier authentifiée n’est revendiquée.','Référent documentaire','Remplacer les vues reconstituées et confirmer l’apparence des hôtes de dialogue.'),
('V15','Traçabilité de bout en bout','Des liens existent ; leur complétude sur chaque série doit être contrôlée.','Stock / expédition','Valider matière racine, série parent, MCP, Stock Entry, SO et bundle livré.'),
('V16','Recette exceptions','L’historique doit rester cohérent après casse successive ou production partielle.','Atelier / stock','Tester unités manquantes, seconde casse, stock épuisé, conflit et verrou soumis.')]
EXERCISES=[
{'id':'X01','title':'Réception de plaques fournisseur','route':'F01 → F02 → F03 → F04 → F07 → F08 → F09','goal':'Deux plaques identifiées et disponibles dans le dépôt matière.','inputs':'Société et fournisseur de formation ; VERRE-CLAIR-6MM ; deux plaques 3210 × 2000 × 6 mm.','actions':['Choisir le circuit d’achat retenu.','Créer la commande puis préparer la réception de deux unités.','Contrôler les dimensions et les séries.','Soumettre selon la procédure de formation.','Vérifier le dépôt et la disponibilité.'],'checks':['□ Une série par unité ; aucune double réception.','□ Total surface = 12,84 m².','□ Épaisseur 6 mm et dimensions positives.','□ Justificatif, mouvement et séries cohérents.'],'next':'A04 / A05'},
{'id':'X02','title':'Commande client avec découpe réussie','route':'C01–C07 → A01–A10 → A26 → S02–S11 → S14 → C08–C13','goal':'Deux ouvrages livrables avec quatre composants DECOUPE-6MM.','inputs':'OUVRAGE-DEMO : facteur 2 DECOUPE ; commande de 2 ouvrages ; dimensions 800 × 600 × 6 mm.','actions':['Préparer devis, dimensions et services.','Créer la commande et confirmer les quatre unités de découpe.','Planifier le MCP avec le kerf réellement retenu pour la recette.','Contrôler et soumettre le Repack de découpe selon le circuit validé.','Préparer la recomposition, puis revenir à la livraison et à la facture.'],'checks':['□ 2 ouvrages × 2 composants = 4 découpes.','□ Surface utile des 4 découpes = 1,92 m².','□ Service PERIMETRE de la ligne parent : 5,6 m pour 2 unités.','□ Aucune seconde consommation de la plaque en recomposition.','□ Aucune double sortie livraison / facture.'],'next':'V01'},
{'id':'X03','title':'Commande avec casse, compensation puis Repack','route':'C07 → A01–A18 → A19–A26 → S02–S09 → C08','goal':'Une unité cassée remplacée sans perdre le lien commercial ni la matière d’origine.','inputs':'MCP de formation ; pièce P2 de l’unité commerciale 2 ; chute interne et sources de stock.','actions':['Désactiver Allow Rotation en Planification pour vérifier l’indépendance de la rotation terrain.','Passer en Retour Terrain ; tester un déplacement à 90° sur une chute 600 × 800.','Annuler ce test puis détruire P2 et appliquer l’incident.','Calculer la compensation interne puis tester les variantes stock / plaque entière.','Vérifier annulation, confirmation, casse successive et contrôle du plan effectif.','Préparer le Repack sur le scénario réellement approuvé.'],'checks':['□ Trois conformes + un besoin restant après la casse.','□ Une seule unité commerciale est remplacée.','□ La rotation terrain fonctionne avec case initiale décochée.','□ Calculer ne sauvegarde pas ; Valider confirme la compensation.','□ Réinitialiser exige un avertissement ; annuler ne supprime rien.','□ Production déjà soumise figée.'],'next':'V01'}]
GLOSSARY=[('MCP','Material Cutting Plan ; rapproche les besoins de découpe et la matière.'),('Plan initial','Référence sauvegardée après Planification.'),('Plan effectif','Résultat tenant compte des incidents et compensations enregistrés.'),('Retour Terrain','Mode de constat des résultats réels de coupe.'),('Serial No','Identifiant d’une unité physique sérialisée.'),('Bundle','Serial and Batch Bundle ; groupe les séries d’une ligne de mouvement.'),('Full / Partial','États matériels : entier / partiellement utilisé.'),('Is Qualified','Matière admise au calcul.'),('Is Active Input','Matière réellement utilisée par le plan.'),('DECOUPE','Pièce dimensionnée issue d’une matière source.'),('OUVRAGE','Article composite, avec composants et facteurs de quantité.'),('Kerf','Largeur de matière perdue par le trait de coupe, en millimètres.'),('Chute / Leftover','Reste conservé et potentiellement réutilisable.'),('Chute en L / Single','Reste physique dont une encoche supérieure gauche est retirée.'),('Destroy','Déclaration de matière détruite, indisponible comme sortie conforme.'),('Compensation','Remplacement des unités commerciales restant à produire.'),('Repack découpe','Consomme la matière et produit des pièces / chutes.'),('Repack recomposition','Consomme des composants disponibles et produit un ouvrage.'),('Brouillon','Document enregistré mais non soumis.'),('Soumettre','Valider le document selon les règles ERPNext ; distinct d’un aperçu.'),('mm² → m²','Diviser par 1 000 000.'),('Périmètre en m','2 × (longueur + largeur en mm) / 1 000.')]
